function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 40000) return 's must have 1 to 4 * 10^4 characters.';
  if (!/^[01]+$/.test(s)) return "s may contain only '0' and '1'.";
  return null;
}

