function numberOfSubstrings(s) {
  const n = s.length;
  const nextZero = new Array(n + 1).fill(n);
  for (let i = n - 1; i >= 0; i--) {
    nextZero[i] = s[i] === '0' ? i : nextZero[i + 1];
  }

  let count = 0;
  for (let left = 0; left < n; left++) {
    let blockStart = left;
    let blockEnd = nextZero[left];
    for (let zeros = 0; blockStart < n; zeros++) {
      const minLength = zeros * zeros + zeros;
      if (left + minLength > n) {
        break;
      }
      const firstRight = Math.max(blockStart, left + minLength - 1);
      count += Math.max(0, blockEnd - firstRight);
      blockStart = blockEnd;
      blockEnd = blockEnd < n ? nextZero[blockEnd + 1] : n;
    }
  }
  return count;
}

