function numberOfSubstrings(s) {
  // Try every substring, keeping running counts of its zeros and ones.
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    let zeros = 0, ones = 0;
    for (let j = i; j < s.length; j++) {
      if (s[j] === '0') zeros++; else ones++;
      if (ones >= zeros * zeros) total++;
    }
  }
  return total;
}

