function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 14);
  // 0: all ones, 1: a zero every few places, 2-4: random with more or fewer ones.
  const shape = Math.floor(rand() * 5);
  const gap = 2 + Math.floor(rand() * (size === 'large' ? 120 : 5));
  const density = [1, 1, 0.97, 0.8, 0.5][shape];
  let s = '';
  for (let i = 0; i < n; i++) {
    if (shape === 1) s += i % gap === gap - 1 ? '0' : '1';
    else s += rand() < (size === 'large' ? density : rand()) ? '1' : '0';
  }
  return [s];
}
